public class AssetBundleImportJobFactory(string resourceName = null, Action<Humidifier.QuickSight.AssetBundleImportJob> factoryAction = null) : ResourceFactory<Humidifier.QuickSight.AssetBundleImportJob>(resourceName)
{

    internal InnerAssetBundleImportJobAssetBundleImportSourceDescriptionFactory AssetBundleImportSourceFactory { get; set; }

    internal InnerAssetBundleImportJobAssetBundleImportJobOverrideValidationStrategyFactory OverrideValidationStrategyFactory { get; set; }

    protected override Humidifier.QuickSight.AssetBundleImportJob Create()
    {
        var assetBundleImportJobResult = CreateAssetBundleImportJob();
        factoryAction?.Invoke(assetBundleImportJobResult);

        return assetBundleImportJobResult;
    }

    private Humidifier.QuickSight.AssetBundleImportJob CreateAssetBundleImportJob()
    {
        var assetBundleImportJobResult = new Humidifier.QuickSight.AssetBundleImportJob
        {
            GivenName = InputResourceName,
        };

        return assetBundleImportJobResult;
    }
    public override void CreateChildren(Humidifier.QuickSight.AssetBundleImportJob result)
    {
        base.CreateChildren(result);

        result.AssetBundleImportSource ??= AssetBundleImportSourceFactory?.Build();
        result.OverrideValidationStrategy ??= OverrideValidationStrategyFactory?.Build();
    }

} // End Of Class

